import fs from 'node:fs';
import PDFDocument from 'pdfkit';
import { BRAND } from '../brand.js';

/*
 * Professional, branded PDF report:
 *  - cover band with the company logo, report title, period and "Generated by … on …"
 *  - KPI cards, follower trend chart, net-growth bar chart
 *  - styled tables (accounts, KPIs, reviews, action plan), insights and summary
 *  - logo + "CONFIDENTIAL" watermark and a contact footer with page numbers on every page
 */

const C = {
  ink: '#0f1b33', muted: '#5b6676', faint: '#8a95a5', line: '#dfe5ee', soft: '#f3f6fa',
  navy: BRAND.colors.navy, navy2: BRAND.colors.navy2, blue: BRAND.colors.blue, cyan: BRAND.colors.cyan,
  green: BRAND.colors.green, greenDark: BRAND.colors.greenDark, red: '#c2372f', amber: '#b07412',
};
const SERIES = ['#1a5fe0', '#16b97a', '#12b5e8', '#7a3fb0', '#e0812a', '#c2372f', '#0b7f66', '#b03a6b'];

const fmt = (n, d = 0) => (n === null || n === undefined || Number.isNaN(Number(n)) ? '—' : Number(n).toLocaleString('en-US', { maximumFractionDigits: d }));
const signed = (n) => (n === null || n === undefined ? '—' : `${n > 0 ? '+' : ''}${fmt(n)}`);
const day = (d) => new Date(String(d).slice(0, 10) + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
const short = (d) => new Date(String(d).slice(0, 10) + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });

export function renderReportPdf(report) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margins: { top: 56, bottom: 70, left: 48, right: 48 }, bufferPages: true, info: { Title: report.title, Author: BRAND.legal, Creator: BRAND.app } });
    const chunks = [];
    doc.on('data', (c) => chunks.push(c));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const d = report.data;
    const L = 48;
    const W = doc.page.width - 96;
    const bottom = () => doc.page.height - 78;
    const hasLogo = fs.existsSync(BRAND.logo);
    const ensure = (h) => { if (doc.y + h > bottom()) { doc.addPage(); doc.y = 56; } };

    /* ---------- cover band ---------- */
    const bandH = 150;
    const grad = doc.linearGradient(0, 0, doc.page.width, bandH);
    grad.stop(0, C.navy).stop(0.65, C.navy2).stop(1, '#0d3b6e');
    doc.rect(0, 0, doc.page.width, bandH).fill(grad);
    const accent = doc.linearGradient(0, bandH - 4, doc.page.width, bandH);
    accent.stop(0, C.blue).stop(0.5, C.cyan).stop(1, C.green);
    doc.rect(0, bandH - 4, doc.page.width, 4).fill(accent);
    if (hasLogo) doc.image(BRAND.logo, L, 26, { width: 92, height: 92 });
    const tx = hasLogo ? L + 110 : L;
    doc.fillColor('#9fd8ff').font('Helvetica-Bold').fontSize(9).text(BRAND.legal.toUpperCase(), tx, 30, { characterSpacing: 1, width: W - (tx - L) });
    doc.fillColor('#ffffff').font('Helvetica-Bold').fontSize(20).text(report.title, tx, 46, { width: W - (tx - L) });
    doc.fillColor('#c9d6ea').font('Helvetica').fontSize(10)
      .text(`Reporting period: ${day(d.range.start)} – ${day(d.range.end)}`, tx, doc.y + 4, { width: W - (tx - L) });
    const generated = new Date(report.created_at || Date.now());
    doc.text(`Generated by ${report.created_by_name || BRAND.ceo} on ${generated.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })} at ${generated.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: process.env.APP_TIMEZONE || 'Asia/Karachi' })}`, tx, doc.y + 2, { width: W - (tx - L) });
    doc.y = bandH + 22;

    /* ---------- helpers ---------- */
    const heading = (t, sub) => {
      ensure(70);
      doc.moveDown(0.6);
      const y = doc.y;
      doc.rect(L, y + 2, 4, 16).fill(C.blue);
      doc.fillColor(C.ink).font('Helvetica-Bold').fontSize(13.5).text(t, L + 12, y, { width: W - 12 });
      if (sub) doc.fillColor(C.muted).font('Helvetica').fontSize(9).text(sub, L + 12, doc.y + 1, { width: W - 12 });
      doc.moveDown(0.6);
      doc.x = L;
    };

    const table = (cols, rows, opts = {}) => {
      const pad = 6;
      const headH = 22;
      const drawHead = (y) => {
        doc.rect(L, y, W, headH).fill(C.navy);
        let x = L;
        doc.font('Helvetica-Bold').fontSize(8.5).fillColor('#ffffff');
        cols.forEach((c) => { doc.text(c.label, x + pad, y + 7, { width: c.w * W - pad * 2, align: c.align || 'left', lineBreak: false }); x += c.w * W; });
        return y + headH;
      };
      ensure(headH + 24);
      let y = drawHead(doc.y);
      doc.font('Helvetica').fontSize(9);
      rows.forEach((r, i) => {
        const h = Math.max(20, ...cols.map((c) => doc.font(c.bold ? 'Helvetica-Bold' : 'Helvetica').heightOfString(String(r[c.key] ?? '—'), { width: c.w * W - pad * 2 }) + 10));
        if (y + h > bottom()) { doc.addPage(); y = drawHead(56); doc.font('Helvetica').fontSize(9); }
        if (i % 2 === 1) doc.rect(L, y, W, h).fill(C.soft);
        let x = L;
        cols.forEach((c) => {
          const v = r[c.key] ?? '—';
          doc.font(c.bold ? 'Helvetica-Bold' : 'Helvetica').fillColor(c.color ? c.color(r) : C.ink)
            .text(String(v), x + pad, y + 5, { width: c.w * W - pad * 2, align: c.align || 'left' });
          x += c.w * W;
        });
        doc.moveTo(L, y + h).lineTo(L + W, y + h).strokeColor(C.line).lineWidth(0.5).stroke();
        y += h;
      });
      doc.y = y + (opts.after ?? 10);
      doc.x = L;
    };

    /* ---------- KPI cards ---------- */
    const t = d.totals;
    const cards = [
      ['Total followers', fmt(t.end_followers), `${signed(t.net_change)}${t.growth_pct !== null && t.growth_pct !== undefined ? ` (${t.growth_pct}%)` : ''} this period`, t.net_change > 0 ? C.green : t.net_change < 0 ? C.red : C.muted],
      ['Posts published', fmt(t.posts_added), `${fmt(d.accounts?.length)} accounts tracked`, C.muted],
      ['Reach', fmt(t.reach), `Engagement ${t.engagement_rate !== null && t.engagement_rate !== undefined ? t.engagement_rate + '%' : '—'}`, C.muted],
      ['Checklist done', d.checklist?.pct !== null && d.checklist?.pct !== undefined ? `${d.checklist.pct}%` : '—', `DMs answered ${t.response_rate !== null && t.response_rate !== undefined ? t.response_rate + '%' : '—'}`, C.muted],
    ];
    const gap = 10, cw = (W - gap * 3) / 4, ch = 66, cy = doc.y;
    cards.forEach(([label, value, sub, subColor], i) => {
      const x = L + i * (cw + gap);
      doc.roundedRect(x, cy, cw, ch, 6).fillAndStroke('#ffffff', C.line);
      doc.rect(x, cy, cw, 3).fill([C.blue, C.green, C.cyan, C.navy2][i]);
      doc.fillColor(C.muted).font('Helvetica').fontSize(8.5).text(label, x + 10, cy + 11, { width: cw - 20 });
      doc.fillColor(C.ink).font('Helvetica-Bold').fontSize(18).text(value, x + 10, cy + 24, { width: cw - 20 });
      doc.fillColor(subColor).font('Helvetica').fontSize(8).text(sub, x + 10, cy + 48, { width: cw - 20 });
    });
    doc.y = cy + ch + 6;

    /* ---------- follower trend (line chart) ---------- */
    const series = Array.isArray(d.series) ? d.series : [];
    const accounts = d.accounts || [];
    if (series.length > 1 && accounts.length) {
      heading('Follower trend', 'Total followers across all tracked accounts, day by day');
      const totals = series.map((row) => {
        let s = 0, any = false;
        for (const a of accounts) { const v = row[`a${a.id}`]; if (v !== null && v !== undefined) { s += Number(v); any = true; } }
        return any ? s : null;
      });
      const pts = totals.map((v, i) => [i, v]).filter(([, v]) => v !== null);
      if (pts.length > 1) {
        ensure(170);
        const x0 = L + 40, y0 = doc.y + 8, w = W - 50, h = 130;
        const vals = pts.map(([, v]) => v);
        let lo = Math.min(...vals), hi = Math.max(...vals);
        if (lo === hi) { lo -= 1; hi += 1; }
        const padV = (hi - lo) * 0.1; lo -= padV; hi += padV;
        const X = (i) => x0 + (i / (series.length - 1)) * w;
        const Y = (v) => y0 + h - ((v - lo) / (hi - lo)) * h;
        doc.font('Helvetica').fontSize(7.5).fillColor(C.faint);
        for (let k = 0; k <= 4; k++) {
          const v = lo + ((hi - lo) * k) / 4, yy = Y(v);
          doc.moveTo(x0, yy).lineTo(x0 + w, yy).strokeColor(C.line).lineWidth(0.5).stroke();
          doc.text(fmt(v, hi - lo < 10 ? 1 : 0), L, yy - 4, { width: 34, align: 'right' });
        }
        const step = Math.max(1, Math.ceil(series.length / 7));
        series.forEach((row, i) => { if (i % step === 0 || i === series.length - 1) doc.fillColor(C.faint).text(short(row.date), X(i) - 20, y0 + h + 5, { width: 40, align: 'center' }); });
        // area
        const area = doc.linearGradient(0, y0, 0, y0 + h);
        area.stop(0, C.cyan, 0.28).stop(1, C.cyan, 0.02);
        doc.moveTo(X(pts[0][0]), y0 + h);
        pts.forEach(([i, v]) => doc.lineTo(X(i), Y(v)));
        doc.lineTo(X(pts[pts.length - 1][0]), y0 + h).closePath().fill(area);
        // line
        doc.moveTo(X(pts[0][0]), Y(pts[0][1]));
        pts.slice(1).forEach(([i, v]) => doc.lineTo(X(i), Y(v)));
        doc.strokeColor(C.blue).lineWidth(2).stroke();
        const [li, lv] = pts[pts.length - 1];
        doc.circle(X(li), Y(lv), 3).fill(C.blue);
        doc.y = y0 + h + 22;
      }
    }

    /* ---------- net growth by account (bar chart) ---------- */
    const withNet = accounts.filter((a) => a.net_change !== null && a.net_change !== undefined);
    if (withNet.length) {
      heading('New followers by account', 'Net change in followers during the reporting period');
      const rowH = 18, labelW = 150;
      ensure(withNet.length * rowH + 20);
      const max = Math.max(1, ...withNet.map((a) => Math.abs(a.net_change)));
      const barW = W - labelW - 60;
      withNet.sort((a, b) => b.net_change - a.net_change).forEach((a, i) => {
        ensure(rowH + 4);
        const y = doc.y;
        doc.fillColor(C.ink).font('Helvetica').fontSize(8.5).text(`${a.brand}`, L, y + 4, { width: labelW - 8, lineBreak: false, ellipsis: true });
        const len = Math.max(2, (Math.abs(a.net_change) / max) * barW);
        doc.roundedRect(L + labelW, y + 3, len, rowH - 7, 3).fill(a.net_change >= 0 ? SERIES[i % SERIES.length] : C.red);
        doc.fillColor(a.net_change >= 0 ? C.ink : C.red).font('Helvetica-Bold').fontSize(8.5).text(signed(a.net_change), L + labelW + len + 6, y + 4, { width: 60 });
        doc.y = y + rowH;
      });
      doc.moveDown(0.5);
    }

    /* ---------- accounts table ---------- */
    heading('Growth by account');
    table(
      [
        { key: 'brand', label: 'Account', w: 0.26, bold: true },
        { key: 'start', label: 'Start', w: 0.1, align: 'right' },
        { key: 'end', label: 'End', w: 0.1, align: 'right' },
        { key: 'net', label: 'Net', w: 0.1, align: 'right', color: (r) => (r._net > 0 ? C.greenDark : r._net < 0 ? C.red : C.ink) },
        { key: 'growth', label: 'Growth', w: 0.1, align: 'right' },
        { key: 'posts', label: 'Posts', w: 0.07, align: 'right' },
        { key: 'reach', label: 'Reach', w: 0.1, align: 'right' },
        { key: 'er', label: 'Eng.', w: 0.08, align: 'right' },
        { key: 'rating', label: 'Rating', w: 0.08, align: 'right' },
      ],
      accounts.map((a) => ({
        brand: `${a.brand}\n@${a.username}`, start: fmt(a.start_followers), end: fmt(a.end_followers),
        net: signed(a.net_change), _net: a.net_change, growth: a.growth_pct !== null && a.growth_pct !== undefined ? `${a.growth_pct}%` : '—',
        posts: fmt(a.posts_added), reach: fmt(a.reach), er: a.engagement_rate !== null && a.engagement_rate !== undefined ? `${a.engagement_rate}%` : '—',
        rating: a.rating ? `${a.rating}/5` : '—',
      }))
    );

    if (d.kpis?.length) {
      heading('Key business numbers', 'Targets and actuals for the period');
      table(
        [
          { key: 'name', label: 'Metric', w: 0.38, bold: true },
          { key: 'target', label: 'Target', w: 0.14, align: 'right' },
          { key: 'value', label: 'Actual', w: 0.14, align: 'right' },
          { key: 'previous', label: 'Previous', w: 0.14, align: 'right' },
          { key: 'status', label: 'Status', w: 0.2, color: (r) => (r.status === 'On track' ? C.greenDark : r.status === 'Off track' ? C.red : C.muted) },
        ],
        d.kpis.map((k) => ({ name: k.unit ? `${k.name} (${k.unit})` : k.name, target: fmt(k.target, 1), value: fmt(k.value, 1), previous: fmt(k.previous, 1), status: k.status === 'on' ? 'On track' : k.status === 'off' ? 'Off track' : '—' }))
      );
    }

    if (d.insights?.length) {
      heading('Key insights');
      d.insights.forEach((i) => {
        ensure(34);
        const col = i.tone === 'good' ? C.green : i.tone === 'risk' || i.tone === 'warn' ? C.red : C.blue;
        const y = doc.y;
        const h = doc.font('Helvetica').fontSize(9.5).heightOfString(i.text, { width: W - 26 }) + 12;
        doc.roundedRect(L, y, W, h, 5).fill(C.soft);
        doc.rect(L, y, 3, h).fill(col);
        doc.fillColor(C.ink).text(i.text, L + 14, y + 6, { width: W - 26 });
        doc.y = y + h + 6;
      });
    }

    const reviews = (d.reviews || []).filter((r) => r.best_post || r.weakest || r.fix_next || r.why_worked);
    if (reviews.length) {
      heading('Account-wise analysis');
      table(
        [
          { key: 'brand', label: 'Account', w: 0.16, bold: true },
          { key: 'best_post', label: 'Best post', w: 0.21 },
          { key: 'why_worked', label: 'Why it worked', w: 0.21 },
          { key: 'weakest', label: 'Weakest / issue', w: 0.21 },
          { key: 'fix_next', label: 'Next month', w: 0.21 },
        ],
        reviews
      );
    }

    const s = d.summary;
    if (s && (s.what_worked || s.what_didnt || s.what_change)) {
      heading('Overall summary');
      [['What worked', s.what_worked, C.green], ['What did not', s.what_didnt, C.red], ['What to change', s.what_change, C.blue]].forEach(([l, v, col]) => {
        if (!v) return;
        ensure(44);
        doc.fillColor(col).font('Helvetica-Bold').fontSize(10).text(l, L);
        doc.fillColor(C.ink).font('Helvetica').fontSize(9.5).text(v, L, doc.y + 2, { width: W });
        doc.moveDown(0.6);
      });
    }

    if (d.actions?.length) {
      heading('Action plan');
      table(
        [
          { key: 'title', label: 'Action', w: 0.44, bold: true },
          { key: 'brand', label: 'Account', w: 0.18 },
          { key: 'owner', label: 'Owner', w: 0.14 },
          { key: 'deadline', label: 'Deadline', w: 0.14 },
          { key: 'done', label: 'Status', w: 0.1, color: (r) => (r.done === 'Done' ? C.greenDark : C.amber) },
        ],
        d.actions.map((a) => ({ ...a, brand: a.brand || 'All', owner: a.owner || '—', deadline: a.deadline ? short(a.deadline) : '—', done: a.done ? 'Done' : 'Open' }))
      );
    }

    // Sign-off
    // Sign-off only when it fits on the last page (never start a page just for it)
    if (doc.y + 50 < bottom()) {
    doc.moveDown(1);
    doc.moveTo(L, doc.y).lineTo(L + 180, doc.y).strokeColor(C.line).lineWidth(1).stroke();
    doc.fillColor(C.ink).font('Helvetica-Bold').fontSize(10).text(`${BRAND.ceo}`, L, doc.y + 6);
    doc.fillColor(C.muted).font('Helvetica').fontSize(9).text(`${BRAND.ceoTitle}, ${BRAND.legal}`, L);
    }

    /* ---------- watermark + footer on every page ---------- */
    const range = doc.bufferedPageRange();
    for (let i = range.start; i < range.start + range.count; i++) {
      doc.switchToPage(i);
      doc.page.margins.bottom = 0;
      const cx = doc.page.width / 2, cyy = doc.page.height / 2 + 30;
      doc.save();
      if (hasLogo) { doc.opacity(0.04); doc.image(BRAND.logo, cx - 140, cyy - 140, { width: 280, height: 280 }); }
      doc.opacity(0.055).fillColor(C.navy).font('Helvetica-Bold').fontSize(30);
      doc.rotate(-35, { origin: [cx, cyy] });
      doc.text('RESILIENCE TECHNOLOGIES LABS', cx - 300, cyy - 16, { width: 600, align: 'center', lineBreak: false });
      doc.fontSize(15).text('CONFIDENTIAL  ·  GROWTH DESK FOR RTL', cx - 300, cyy + 22, { width: 600, align: 'center', characterSpacing: 3, lineBreak: false });
      doc.restore();

      const fy = doc.page.height - 50;
      doc.moveTo(L, fy - 8).lineTo(L + W, fy - 8).strokeColor(C.line).lineWidth(0.7).stroke();
      if (hasLogo) doc.image(BRAND.logo, L, fy - 2, { width: 22, height: 22 });
      doc.fillColor(C.ink).font('Helvetica-Bold').fontSize(8).text(`${BRAND.app}  ·  ${BRAND.legal}`, L + 28, fy - 1, { width: W - 120, lineBreak: false });
      doc.fillColor(C.muted).font('Helvetica').fontSize(7.5).text(`CEO ${BRAND.ceo}  ·  ${BRAND.email}  ·  ${BRAND.phone}  ·  ${BRAND.website}`, L + 28, fy + 10, { width: W - 120, lineBreak: false });
      doc.fillColor(C.muted).font('Helvetica').fontSize(8).text(`Page ${i + 1} of ${range.count}`, L + W - 90, fy + 3, { width: 90, align: 'right', lineBreak: false });
    }
    doc.end();
  });
}
